const res = await client.messages.create({ model, max_tokens: 4096, tools, messages });
if (res.stop_reason === "tool_use") {
  await runTools(res.content);
} else if (res.stop_reason === "end_turn") {
  return JSON.parse(textOf(res.content));
}
// other stop reasons fall through

const toolUses = res.content.filter(b => b.type === "tool_use");
const first = toolUses[0];
const output = await runTool(first.name, first.input);
messages.push({ role: "assistant", content: res.content });
messages.push({ role: "user", content: [
  { type: "tool_result", tool_use_id: first.id, content: output },
]});
